WITH returns_2022 AS (SELECT cc.cc_call_center_sk, cc.cc_name, d_open.d_date AS open_date, d_close.d_date AS closed_date, COALESCE(cr.cr_net_loss,0) AS catalog_net_loss, COALESCE(sr.sr_net_loss,0) AS store_net_loss FROM call_center cc LEFT JOIN date_dim d_open ON cc.cc_open_date_sk = d_open.d_date_sk LEFT JOIN date_dim d_close ON cc.cc_closed_date_sk = d_close.d_date_sk JOIN catalog_returns cr ON cc.cc_call_center_sk = cr.cr_call_center_sk JOIN date_dim d_ret ON cr.cr_returned_date_sk = d_ret.d_date_sk LEFT JOIN store_returns sr ON sr.sr_returned_date_sk = d_ret.d_date_sk WHERE d_ret.d_year = 2022), totals AS (SELECT cc_name, open_date, closed_date, SUM(catalog_net_loss) AS total_catalog_net_loss, SUM(store_net_loss) AS total_store_net_loss, SUM(catalog_net_loss + store_net_loss) AS combined_net_loss FROM returns_2022 GROUP BY cc_name, open_date, closed_date) SELECT cc_name, open_date, closed_date, total_catalog_net_loss, total_store_net_loss, combined_net_loss, RANK() OVER (ORDER BY combined_net_loss DESC) AS loss_rank, SUM(combined_net_loss) OVER (ORDER BY combined_net_loss DESC) AS cumulative_net_loss, CASE WHEN combined_net_loss > 200000 THEN 'High' WHEN combined_net_loss > 100000 THEN 'Medium' ELSE 'Low' END AS loss_category FROM totals ORDER BY combined_net_loss DESC LIMIT 5
